WITH зав AS (SELECT DISTINCT split_part(trim(f.detail), ' ', 1) AS имя FROM code_fact f WHERE f.project_id = $1 AND f.kind = 'direct-dep' AND split_part(trim(f.detail), ' ', 1) ~ '^[a-z]' AND NOT EXISTS (SELECT 1 FROM code_fact p WHERE p.project_id = $1 AND p.kind = 'direct-dep' AND p.detail LIKE '%path =%' AND split_part(trim(p.detail), ' ', 1) = split_part(trim(f.detail), ' ', 1)) AND NOT EXISTS (SELECT 1 FROM scheme($1) k WHERE k.role = 'word.manifest-key' AND k.value = split_part(trim(f.detail), ' ', 1))) SELECT 'датчик зависимостей ' || fact_gap($1, 'direct-dep') || ': названы ли они решением — неизвестно' AS detail WHERE NOT fact_fresh($1, 'direct-dep') UNION ALL SELECT з.имя || ' — прямая зависимость, которую не называет ни одно решение' FROM зав з WHERE fact_fresh($1, 'direct-dep') AND NOT EXISTS (SELECT 1 FROM project_documents d WHERE d.project_id = $1 AND d.entity_kind = 'decision' AND d.content ~ ('\y' || з.имя || '\y')) ORDER BY 1
